const BASE_URL = "{{BASE_URL}}";
const API_KEY = "{{API_KEY}}";
const jobId = "job_3f9c2a7e5b8d4c1fa0e6b2d9c7f41a58";

const resp = await fetch(`${BASE_URL}/v1/jobs/${jobId}/artifacts`, {
  headers: { Authorization: `Bearer ${API_KEY}` },
});
if (!resp.ok) throw new Error(JSON.stringify(await resp.json()));
const { data } = await resp.json();
const outputs = data.filter((a) => a.type === "output");
console.log(outputs.map((a) => `${a.artifact_id} ${a.filename}`));
